    grid.attach(&search_button, 0, 1, 1, 1);

    grid.attach(&whisper_model_combo, 0, 2, 1, 1);
    grid.attach(&second_plane_check, 0, 3, 1, 1);

    // Coluna 1: Info e Botões (Alinhados à direita ou ocupando a segunda metade)
